import { useState, useEffect } from "react";
import { Trophy, X, Medal, Crown, RefreshCw, User, Sprout, ChevronRight } from "lucide-react";
import { fetchRanking, RankingPlayer } from "@/utils/rankingApi";
import { getUserInfo } from "@/utils/userInfo";
import { SEED_CONFIGS, SeedType } from "@/types/game";
import PlayerFarmModal from "./PlayerFarmModal";

interface RankingModalProps {
  open: boolean;
  onClose: () => void;
}

export default function RankingModal({ open, onClose }: RankingModalProps) {
  const [ranking, setRanking] = useState<RankingPlayer[]>([]);
  const [loading, setLoading] = useState(false);
  const [myUuid, setMyUuid] = useState("");
  const [myNickname, setMyNickname] = useState("");
  const [myBestLevel] = useState(() => parseInt(localStorage.getItem("block_game_best") || "0"));
  const [farmPlayer, setFarmPlayer] = useState<RankingPlayer | null>(null);

  useEffect(() => {
    if (!open) return;
    const userInfo = getUserInfo();
    setMyUuid(userInfo.uuid);
    setMyNickname(userInfo.nickname);
    loadRanking();
  }, [open]);

  const loadRanking = async (force = false) => {
    setLoading(true);
    const data = await fetchRanking(force);
    setRanking(data);
    setLoading(false);
  };

  if (!open) return null;

  const getRankIcon = (index: number) => {
    if (index === 0) return <Crown size={20} className="text-amber-400" />;
    if (index === 1) return <Medal size={20} className="text-slate-300" />;
    if (index === 2) return <Medal size={20} className="text-orange-400" />;
    return <span className="text-slate-500 font-bold text-sm w-5 text-center">{index + 1}</span>;
  };

  const getRankBg = (index: number) => {
    if (index === 0) return "bg-gradient-to-r from-amber-500/20 to-yellow-500/10 border-amber-400/40";
    if (index === 1) return "bg-gradient-to-r from-slate-400/15 to-slate-300/5 border-slate-400/30";
    if (index === 2) return "bg-gradient-to-r from-orange-500/15 to-amber-500/5 border-orange-400/30";
    return "bg-slate-800/30 border-slate-700/30";
  };

  const getFarmStatus = (player: RankingPlayer) => {
    const farm = player.farmData;
    if (!farm) return { hasCrops: false, matureCount: 0, growingCount: 0 };
    let matureCount = 0;
    let growingCount = 0;
    for (const crop of farm.plantedCrops) {
      const config = SEED_CONFIGS[crop.seedType as SeedType];
      if (!config) continue;
      const elapsedMs = Date.now() - crop.plantedAt;
      const totalMs = config.growthHours * 60 * 60 * 1000;
      if (elapsedMs >= totalMs) {
        matureCount++;
      } else {
        growingCount++;
      }
    }
    return { hasCrops: farm.plantedCrops.length > 0, matureCount, growingCount };
  };

  const myRankIndex = ranking.findIndex((p) => p.uuid === myUuid);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/80 backdrop-blur-md" onClick={onClose} />
      <div className="relative bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 border border-amber-500/30 rounded-3xl p-6 sm:p-8 max-w-sm w-full shadow-2xl max-h-[85vh] flex flex-col">
        <div className="absolute -top-6 left-1/2 -translate-x-1/2">
          <div className="w-12 h-12 rounded-full bg-gradient-to-br from-amber-400 to-orange-500 flex items-center justify-center shadow-lg shadow-amber-500/50">
            <Trophy className="text-white" size={24} />
          </div>
        </div>

        <button
          onClick={onClose}
          className="absolute top-4 right-4 p-2 rounded-full hover:bg-slate-700/50 text-slate-400 hover:text-slate-200 transition-all"
        >
          <X size={20} />
        </button>

        <h2 className="text-2xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-amber-400 via-orange-400 to-yellow-400 mb-4 mt-4 text-center">
          最高关卡排行
        </h2>

        {myBestLevel > 0 && (
          <div className={`mb-4 p-3 rounded-xl border ${myRankIndex >= 0 ? getRankBg(myRankIndex) : "bg-slate-800/30 border-slate-700/30"}`}>
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-full bg-gradient-to-br from-violet-500 to-purple-600 flex items-center justify-center shrink-0">
                <User size={18} className="text-white" />
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-slate-200 font-semibold truncate">{myNickname}</p>
                <p className="text-slate-400 text-xs">
                  {myRankIndex >= 0 ? `当前排名 #${myRankIndex + 1}` : "暂未上榜"}
                </p>
              </div>
              <div className="text-right">
                <p className="text-amber-400 font-bold text-lg">{myBestLevel}</p>
                <p className="text-slate-500 text-xs">最高关卡</p>
              </div>
            </div>
          </div>
        )}

        <div className="flex items-center justify-between mb-3">
          <p className="text-slate-400 text-sm">
            共 <span className="text-amber-400 font-bold">{ranking.length}</span> 位玩家
          </p>
          <button
            onClick={() => loadRanking(true)}
            disabled={loading}
            className="p-1.5 rounded-lg hover:bg-slate-700/50 text-slate-400 hover:text-slate-200 transition-all disabled:opacity-40"
          >
            <RefreshCw size={16} className={loading ? "animate-spin" : ""} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto space-y-2 pr-1 -mr-1">
          {loading ? (
            <div className="text-center py-12 text-slate-500">
              <RefreshCw size={24} className="mx-auto mb-3 animate-spin text-amber-400" />
              <p>加载排行榜中...</p>
            </div>
          ) : ranking.length === 0 ? (
            <div className="text-center py-12 text-slate-500">
              <Trophy size={32} className="mx-auto mb-3 text-slate-600" />
              <p>暂无排行数据</p>
              <p className="text-xs mt-1 text-slate-600">刷新最高关卡即可上榜</p>
            </div>
          ) : (
            ranking.map((player, index) => {
              const isMe = player.uuid === myUuid;
              const farmStatus = getFarmStatus(player);
              const hasFarm = !!player.farmData;
              return (
                <button
                  key={player.uuid}
                  onClick={() => {
                    if (isMe) {
                      onClose();
                      window.location.hash = "#/farm";
                    } else {
                      setFarmPlayer(player);
                    }
                  }}
                  className={`w-full flex items-center gap-3 p-3 rounded-xl border transition-all active:scale-[0.98] ${
                    isMe
                      ? "bg-gradient-to-r from-violet-500/20 to-purple-500/10 border-violet-400/40 hover:from-violet-500/30 hover:to-purple-500/20"
                      : `${getRankBg(index)} hover:border-slate-500/50`
                  }`}
                >
                  <div className="w-7 flex items-center justify-center shrink-0">
                    {getRankIcon(index)}
                  </div>
                  <div className="w-9 h-9 rounded-full bg-gradient-to-br from-slate-600 to-slate-700 flex items-center justify-center shrink-0">
                    <span className="text-slate-200 text-sm font-bold">
                      {player.nickname.charAt(0).toUpperCase()}
                    </span>
                  </div>
                  <div className="flex-1 min-w-0 text-left">
                    <p className={`font-semibold truncate ${isMe ? "text-violet-200" : "text-slate-200"}`}>
                      {player.nickname}
                      {isMe && <span className="text-violet-400 text-xs ml-1">(我)</span>}
                    </p>
                    <p className="text-slate-500 text-xs flex items-center gap-1">
                      {player.updatedAt && !isNaN(new Date(player.updatedAt).getTime())
                        ? new Date(player.updatedAt).toLocaleDateString("zh-CN")
                        : "—"}
                      {hasFarm && (
                        <>
                          <span className="text-slate-600">·</span>
                          {farmStatus.matureCount > 0 ? (
                            <>
                              <span className="text-emerald-400">✓</span>
                              <span className="text-emerald-400/80">{farmStatus.matureCount}成熟</span>
                            </>
                          ) : farmStatus.growingCount > 0 ? (
                            <>
                              <Sprout size={10} className="text-amber-400" />
                              <span className="text-amber-400/80">{farmStatus.growingCount}生长中</span>
                            </>
                          ) : (
                            <>
                              <Sprout size={10} className="text-slate-500" />
                              <span className="text-slate-500">空地</span>
                            </>
                          )}
                        </>
                      )}
                    </p>
                  </div>
                  <div className="flex items-center gap-2">
                    <div className="text-right">
                      <p className={`font-bold text-lg ${index < 3 ? "text-amber-400" : "text-slate-300"}`}>
                        {player.bestLevel}
                      </p>
                      <p className="text-slate-500 text-xs">关</p>
                    </div>
                    <ChevronRight size={16} className="text-slate-500 shrink-0" />
                  </div>
                </button>
              );
            })
          )}
        </div>
      </div>
      <PlayerFarmModal
        open={farmPlayer !== null}
        onClose={() => setFarmPlayer(null)}
        player={farmPlayer}
      />
    </div>
  );
}
