import { useFarmStore } from "@/store/useFarmStore";
import { uploadFarmData } from "@/utils/rankingApi";
import { getUserInfo } from "@/utils/userInfo";
import { showToast } from "@/utils/toast";

const DEBOUNCE_MS = 5 * 1000;
const MAX_RETRY_MS = 8 * 1000;

let debounceTimer: number | null = null;
let retryTimer: number | null = null;
let retryCount = 0;
let initialized = false;

function clearRetry() {
  if (retryTimer !== null) {
    clearTimeout(retryTimer);
    retryTimer = null;
  }
}

function scheduleRetry() {
  clearRetry();
  retryCount += 1;
  const delay = Math.min(1000 * Math.pow(2, retryCount), MAX_RETRY_MS);
  retryTimer = window.setTimeout(() => {
    retryTimer = null;
    doSync();
  }, delay);
}

async function doSync() {
  const farmState = useFarmStore.getState();
  const dirty = farmState._consumeFieldDirty();
  if (!dirty) return;

  const userInfo = getUserInfo();
  if (!userInfo.uuid) return;

  const farmData = {
    plantedCrops: farmState.plantedCrops.map((c) => ({
      id: c.id,
      seedType: c.seedType,
      plantedAt: c.plantedAt,
      plotIndex: c.plotIndex,
    })),
    stolenRecords: farmState.stolenRecords || [],
    warehouse: farmState.warehouse,
    totalPlots: farmState.totalPlots,
    openedPlots: farmState.openedPlots,
    unlockedSeeds: farmState.unlockedSeeds,
    snapshotAt: Date.now(),
  };

  const ok = await uploadFarmData(userInfo.uuid, userInfo.nickname, farmData);
  if (ok) {
    retryCount = 0;
    clearRetry();
  } else {
    useFarmStore.getState()._markFieldDirty();
    if (retryCount < 3) {
      scheduleRetry();
    } else {
      showToast("农场数据同步失败，请稍后再试", "error");
      retryCount = 0;
    }
  }
}

function scheduleSync() {
  const farmState = useFarmStore.getState();
  if (!farmState._fieldDirty) return;

  if (debounceTimer !== null) {
    clearTimeout(debounceTimer);
  }
  debounceTimer = window.setTimeout(() => {
    debounceTimer = null;
    doSync();
  }, DEBOUNCE_MS);
}

export function initFarmSync() {
  if (initialized) return;
  initialized = true;

  const unsubscribe = useFarmStore.subscribe(
    (state, prevState) => {
      if (state._fieldDirty && !prevState._fieldDirty) {
        scheduleSync();
      }
    }
  );

  const handleVisibility = () => {
    if (document.visibilityState === "hidden") {
      if (debounceTimer !== null) {
        clearTimeout(debounceTimer);
        debounceTimer = null;
      }
      doSync();
    }
  };

  document.addEventListener("visibilitychange", handleVisibility);

  return () => {
    unsubscribe();
    document.removeEventListener("visibilitychange", handleVisibility);
    if (debounceTimer !== null) {
      clearTimeout(debounceTimer);
    }
    clearRetry();
    initialized = false;
  };
}
