import { useMemo, useRef, useEffect, useState, useCallback } from "react";
import { useGameStore } from "@/store/useGameStore";
import { ROWS, COLS, Direction, Position } from "@/types/game";
import { findPushChain, maxPhysicalPushSteps, findAdjacentSameType } from "@/utils/gameLogic";
import BrickCell from "./BrickCell";

const LONG_PRESS_MS = 150;
const DRAG_THRESHOLD = 10;
const DOUBLE_CLICK_MS = 300;
const CLEAR_ANIMATION_MS = 350;
const SHAKE_ANIMATION_MS = 500;

export default function GameBoard() {
  const board = useGameStore((s) => s.board);
  const selectedGroup = useGameStore((s) => s.selectedGroup);
  const selectedCell = useGameStore((s) => s.selectedCell);
  const pairCandidates = useGameStore((s) => s.pairCandidates);
  const clearingCells = useGameStore((s) => s.clearingCells);
  const hintCells = useGameStore((s) => s.hintCells);
  const activeTool = useGameStore((s) => s.activeTool);
  const swapFirstCell = useGameStore((s) => s.swapFirstCell);
  const selectCell = useGameStore((s) => s.selectCell);
  const finalizeDragMove = useGameStore((s) => s.finalizeDragMove);
  const finishClearingAnimation = useGameStore((s) => s.finishClearingAnimation);
  const findSameTypePositions = useGameStore((s) => s.findSameTypePositions);
  const clearHint = useGameStore((s) => s.clearHint);

  const boardRef = useRef<HTMLDivElement>(null);
  const gridRef = useRef<HTMLDivElement>(null);
  const longPressTimer = useRef<number | null>(null);
  const dragStartMouse = useRef<{ x: number; y: number } | null>(null);
  const dragStartCell = useRef<{ row: number; col: number } | null>(null);
  const dragAxis = useRef<"horizontal" | "vertical" | null>(null);
  const [dragChain, setDragChain] = useState<Position[] | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const dragOffsetRef = useRef<{ x: number; y: number }>({ x: 0, y: 0 });
  const [dragOffsetTick, setDragOffsetTick] = useState(0);
  const dragStarted = useRef(false);
  const rafId = useRef<number | null>(null);

  const lastClickRef = useRef<{ row: number; col: number; time: number } | null>(null);
  const [shakingCells, setShakingCells] = useState<Set<string>>(new Set());
  const clearAnimTimer = useRef<number | null>(null);
  const shakeAnimTimer = useRef<number | null>(null);

  const groupSet = useMemo(() => {
    const set = new Set<string>();
    if (selectedGroup) {
      for (const pos of selectedGroup.positions) {
        set.add(`${pos.row},${pos.col}`);
      }
    }
    return set;
  }, [selectedGroup]);

  const candidateSet = useMemo(() => {
    const set = new Set<string>();
    for (const pos of pairCandidates) {
      set.add(`${pos.row},${pos.col}`);
    }
    return set;
  }, [pairCandidates]);

  const getCellSize = useCallback(() => {
    if (!gridRef.current) return { w: 44, h: 44, gap: 4 };
    const rect = gridRef.current.getBoundingClientRect();
    const style = window.getComputedStyle(gridRef.current);
    const gap = parseFloat(style.gap) || 4;
    const w = (rect.width - gap * (COLS - 1)) / COLS;
    const h = (rect.height - gap * (ROWS - 1)) / ROWS;
    return { w, h, gap };
  }, []);

  const getDirection = useCallback(
    (dx: number, dy: number): Direction | null => {
      const absX = Math.abs(dx);
      const absY = Math.abs(dy);
      if (absX < DRAG_THRESHOLD && absY < DRAG_THRESHOLD) return null;
      if (absX > absY) {
        return dx > 0 ? "right" : "left";
      } else {
        return dy > 0 ? "down" : "up";
      }
    },
    []
  );

  const scheduleOffsetUpdate = useCallback(() => {
    if (rafId.current !== null) return;
    rafId.current = requestAnimationFrame(() => {
      rafId.current = null;
      setDragOffsetTick((t) => (t + 1) % 1000000);
    });
  }, []);

  const dragDirRef = useRef<Direction | null>(null);
  const totalStepsRef = useRef<number>(0);

  const handleMouseDown = useCallback(
    (e: React.MouseEvent, row: number, col: number) => {
      if (e.button !== 0) return;
      const cell = board[row]?.[col];
      if (!cell || cell.brick === null) return;
      // 冰冻方块不能拖拽
      if (cell.frozen) return;

      dragStartMouse.current = { x: e.clientX, y: e.clientY };
      dragStartCell.current = { row, col };
      dragStarted.current = false;
      dragAxis.current = null;
      dragDirRef.current = null;
      totalStepsRef.current = 0;
      setDragChain(null);
      dragOffsetRef.current = { x: 0, y: 0 };
      if (rafId.current !== null) {
        cancelAnimationFrame(rafId.current);
        rafId.current = null;
      }

      longPressTimer.current = window.setTimeout(() => {
        if (!selectedCell || selectedCell.row !== row || selectedCell.col !== col) {
          selectCell(row, col);
        }
        setIsDragging(true);
        longPressTimer.current = null;
      }, LONG_PRESS_MS);
    },
    [board, selectedCell, selectCell]
  );

  const handleMouseUp = useCallback(() => {
    if (longPressTimer.current) {
      clearTimeout(longPressTimer.current);
      longPressTimer.current = null;
    }
    if (rafId.current !== null) {
      cancelAnimationFrame(rafId.current);
      rafId.current = null;
    }

    const dir = dragDirRef.current;
    const steps = totalStepsRef.current;
    if (dir && steps > 0) {
      finalizeDragMove(dir, steps);
    }

    setIsDragging(false);
    dragOffsetRef.current = { x: 0, y: 0 };
    setDragOffsetTick((t) => (t + 1) % 1000000);
    dragStartMouse.current = null;
    dragStartCell.current = null;
    dragStarted.current = false;
    dragAxis.current = null;
    dragDirRef.current = null;
    totalStepsRef.current = 0;
    setDragChain(null);
  }, [finalizeDragMove]);

  const handleMouseMove = useCallback(
    (e: MouseEvent) => {
      if (!dragStartMouse.current) return;
      const dx = e.clientX - dragStartMouse.current.x;
      const dy = e.clientY - dragStartMouse.current.y;
      const { w, h, gap } = getCellSize();
      const stepW = w + gap;
      const stepH = h + gap;

      if (!isDragging) {
        if (
          !dragStarted.current &&
          (Math.abs(dx) > DRAG_THRESHOLD || Math.abs(dy) > DRAG_THRESHOLD)
        ) {
          if (longPressTimer.current) {
            clearTimeout(longPressTimer.current);
            longPressTimer.current = null;
          }
          dragStarted.current = true;
          if (dragStartCell.current) {
            if (
              !selectedCell ||
              selectedCell.row !== dragStartCell.current.row ||
              selectedCell.col !== dragStartCell.current.col
            ) {
              selectCell(dragStartCell.current.row, dragStartCell.current.col);
            }
          }
          setIsDragging(true);
        }
      }

      if (isDragging && selectedCell) {
        let effectiveDx = dx;
        let effectiveDy = dy;

        if (dragAxis.current === null) {
          if (Math.abs(effectiveDx) > DRAG_THRESHOLD || Math.abs(effectiveDy) > DRAG_THRESHOLD) {
            dragAxis.current = Math.abs(effectiveDx) > Math.abs(effectiveDy) ? "horizontal" : "vertical";
            if (dragAxis.current && dragChain === null) {
              const initDir = dragAxis.current === "horizontal"
                ? (effectiveDx > 0 ? "right" : "left")
                : (effectiveDy > 0 ? "down" : "up");
              setDragChain(findPushChain(board, selectedCell.row, selectedCell.col, initDir));
            }
          }
        }

        if (dragAxis.current === "horizontal") {
          effectiveDy = 0;
        } else if (dragAxis.current === "vertical") {
          effectiveDx = 0;
        }

        let dir: Direction | null = null;
        if (dragAxis.current === "horizontal") {
          if (effectiveDx > 0) dir = "right";
          else if (effectiveDx < 0) dir = "left";
        } else if (dragAxis.current === "vertical") {
          if (effectiveDy > 0) dir = "down";
          else if (effectiveDy < 0) dir = "up";
        }

        if (dir) {
          const stepSize = (dir === "left" || dir === "right") ? stepW : stepH;
          const maxSteps = maxPhysicalPushSteps(board, selectedCell.row, selectedCell.col, dir);

          if (maxSteps === 0) {
            if (dir === "left" || dir === "right") effectiveDx = 0;
            else effectiveDy = 0;
          } else {
            const totalMaxOffset = maxSteps * stepSize;
            if (dir === "right") effectiveDx = Math.min(effectiveDx, totalMaxOffset);
            else if (dir === "left") effectiveDx = Math.max(effectiveDx, -totalMaxOffset);
            else if (dir === "down") effectiveDy = Math.min(effectiveDy, totalMaxOffset);
            else if (dir === "up") effectiveDy = Math.max(effectiveDy, -totalMaxOffset);
          }

          const rawOffset = Math.abs(dir === "left" || dir === "right" ? effectiveDx : effectiveDy);
          const steps = Math.floor((rawOffset + stepSize * 0.4) / stepSize);
          dragDirRef.current = dir;
          totalStepsRef.current = steps;
        } else {
          dragDirRef.current = null;
          totalStepsRef.current = 0;
        }

        dragOffsetRef.current = { x: effectiveDx, y: effectiveDy };
        scheduleOffsetUpdate();
      }
    },
    [isDragging, selectedCell, selectCell, getCellSize, board, dragChain, scheduleOffsetUpdate]
  );

  const handleTouchStart = useCallback(
    (e: React.TouchEvent, row: number, col: number) => {
      const touch = e.touches[0];
      if (!touch) return;
      const cell = board[row]?.[col];
      if (!cell || cell.brick === null) return;
      // 冰冻方块不能拖拽
      if (cell.frozen) return;

      dragStartMouse.current = { x: touch.clientX, y: touch.clientY };
      dragStartCell.current = { row, col };
      dragStarted.current = false;
      dragAxis.current = null;
      dragDirRef.current = null;
      totalStepsRef.current = 0;
      setDragChain(null);
      dragOffsetRef.current = { x: 0, y: 0 };
      if (rafId.current !== null) {
        cancelAnimationFrame(rafId.current);
        rafId.current = null;
      }

      longPressTimer.current = window.setTimeout(() => {
        if (!selectedCell || selectedCell.row !== row || selectedCell.col !== col) {
          selectCell(row, col);
        }
        setIsDragging(true);
        longPressTimer.current = null;
      }, LONG_PRESS_MS);
    },
    [board, selectedCell, selectCell]
  );

  const handleTouchMove = useCallback(
    (e: TouchEvent) => {
      const touch = e.touches[0];
      if (!touch || !dragStartMouse.current) return;
      e.preventDefault();
      const dx = touch.clientX - dragStartMouse.current.x;
      const dy = touch.clientY - dragStartMouse.current.y;
      const { w, h, gap } = getCellSize();
      const stepW = w + gap;
      const stepH = h + gap;

      if (!isDragging) {
        if (
          !dragStarted.current &&
          (Math.abs(dx) > DRAG_THRESHOLD || Math.abs(dy) > DRAG_THRESHOLD)
        ) {
          if (longPressTimer.current) {
            clearTimeout(longPressTimer.current);
            longPressTimer.current = null;
          }
          dragStarted.current = true;
          if (dragStartCell.current) {
            if (
              !selectedCell ||
              selectedCell.row !== dragStartCell.current.row ||
              selectedCell.col !== dragStartCell.current.col
            ) {
              selectCell(dragStartCell.current.row, dragStartCell.current.col);
            }
          }
          setIsDragging(true);
        }
      }

      if (isDragging && selectedCell) {
        let effectiveDx = dx;
        let effectiveDy = dy;

        if (dragAxis.current === null) {
          if (Math.abs(effectiveDx) > DRAG_THRESHOLD || Math.abs(effectiveDy) > DRAG_THRESHOLD) {
            dragAxis.current = Math.abs(effectiveDx) > Math.abs(effectiveDy) ? "horizontal" : "vertical";
            if (dragAxis.current && dragChain === null) {
              const initDir = dragAxis.current === "horizontal"
                ? (effectiveDx > 0 ? "right" : "left")
                : (effectiveDy > 0 ? "down" : "up");
              setDragChain(findPushChain(board, selectedCell.row, selectedCell.col, initDir));
            }
          }
        }

        if (dragAxis.current === "horizontal") {
          effectiveDy = 0;
        } else if (dragAxis.current === "vertical") {
          effectiveDx = 0;
        }

        let dir: Direction | null = null;
        if (dragAxis.current === "horizontal") {
          if (effectiveDx > 0) dir = "right";
          else if (effectiveDx < 0) dir = "left";
        } else if (dragAxis.current === "vertical") {
          if (effectiveDy > 0) dir = "down";
          else if (effectiveDy < 0) dir = "up";
        }

        if (dir) {
          const stepSize = (dir === "left" || dir === "right") ? stepW : stepH;
          const maxSteps = maxPhysicalPushSteps(board, selectedCell.row, selectedCell.col, dir);

          if (maxSteps === 0) {
            if (dir === "left" || dir === "right") effectiveDx = 0;
            else effectiveDy = 0;
          } else {
            const totalMaxOffset = maxSteps * stepSize;
            if (dir === "right") effectiveDx = Math.min(effectiveDx, totalMaxOffset);
            else if (dir === "left") effectiveDx = Math.max(effectiveDx, -totalMaxOffset);
            else if (dir === "down") effectiveDy = Math.min(effectiveDy, totalMaxOffset);
            else if (dir === "up") effectiveDy = Math.max(effectiveDy, -totalMaxOffset);
          }

          const rawOffset = Math.abs(dir === "left" || dir === "right" ? effectiveDx : effectiveDy);
          const steps = Math.floor((rawOffset + stepSize * 0.4) / stepSize);
          dragDirRef.current = dir;
          totalStepsRef.current = steps;
        } else {
          dragDirRef.current = null;
          totalStepsRef.current = 0;
        }

        dragOffsetRef.current = { x: effectiveDx, y: effectiveDy };
        scheduleOffsetUpdate();
      }
    },
    [isDragging, selectedCell, selectCell, getCellSize, board, dragChain, scheduleOffsetUpdate]
  );

  const handleClick = useCallback(
    (row: number, col: number) => {
      if (isDragging || dragStarted.current || longPressTimer.current) return;
      clearHint();

      const now = Date.now();
      const last = lastClickRef.current;
      const isDoubleClick =
        last &&
        last.row === row &&
        last.col === col &&
        now - last.time < DOUBLE_CLICK_MS;

      if (isDoubleClick) {
        lastClickRef.current = null;
        const cell = board[row]?.[col];
        if (!cell || cell.brick === null) return;

        const candidates = findAdjacentSameType(board, row, col);
        if (candidates.length === 1) {
          if (
            !selectedCell ||
            selectedCell.row !== row ||
            selectedCell.col !== col
          ) {
            selectCell(row, col);
          }
          setTimeout(() => {
            selectCell(candidates[0].row, candidates[0].col);
          }, 0);
        } else if (candidates.length > 1) {
          selectCell(row, col);
        } else {
          const sameType = findSameTypePositions(row, col);
          if (sameType.length > 0) {
            const set = new Set<string>();
            for (const p of sameType) {
              set.add(`${p.row},${p.col}`);
            }
            setShakingCells(set);
            if (shakeAnimTimer.current) {
              clearTimeout(shakeAnimTimer.current);
            }
            shakeAnimTimer.current = window.setTimeout(() => {
              setShakingCells(new Set());
            }, SHAKE_ANIMATION_MS);
          }
        }
        return;
      }

      lastClickRef.current = { row, col, time: now };
      selectCell(row, col);
    },
    [isDragging, board, selectedCell, selectCell, findSameTypePositions, clearHint]
  );

  const handleTouchEnd = useCallback(
    () => {
      if (longPressTimer.current) {
        clearTimeout(longPressTimer.current);
        longPressTimer.current = null;
      }
      if (rafId.current !== null) {
        cancelAnimationFrame(rafId.current);
        rafId.current = null;
      }

      if (!dragStarted.current && dragStartCell.current) {
        handleClick(dragStartCell.current.row, dragStartCell.current.col);
      }

      const dir = dragDirRef.current;
      const steps = totalStepsRef.current;
      if (dir && steps > 0) {
        finalizeDragMove(dir, steps);
      }

      setIsDragging(false);
      dragOffsetRef.current = { x: 0, y: 0 };
      setDragOffsetTick((t) => (t + 1) % 1000000);
      dragStartMouse.current = null;
      dragStartCell.current = null;
      dragStarted.current = false;
      dragAxis.current = null;
      dragDirRef.current = null;
      totalStepsRef.current = 0;
      setDragChain(null);
    },
    [finalizeDragMove, handleClick]
  );

  const onCellMouseDown = useCallback(
    (e: React.MouseEvent) => {
      const el = e.currentTarget as HTMLElement;
      const r = parseInt(el.dataset.row || "0", 10);
      const c = parseInt(el.dataset.col || "0", 10);
      handleMouseDown(e, r, c);
    },
    [handleMouseDown]
  );

  const onCellClick = useCallback(
    (e: React.MouseEvent) => {
      const el = e.currentTarget as HTMLElement;
      const r = parseInt(el.dataset.row || "0", 10);
      const c = parseInt(el.dataset.col || "0", 10);
      handleClick(r, c);
    },
    [handleClick]
  );

  const onCellTouchStart = useCallback(
    (e: React.TouchEvent) => {
      const el = e.currentTarget as HTMLElement;
      const r = parseInt(el.dataset.row || "0", 10);
      const c = parseInt(el.dataset.col || "0", 10);
      handleTouchStart(e, r, c);
    },
    [handleTouchStart]
  );

  useEffect(() => {
    if (clearingCells.length > 0) {
      if (clearAnimTimer.current) {
        clearTimeout(clearAnimTimer.current);
      }
      clearAnimTimer.current = window.setTimeout(() => {
        finishClearingAnimation();
      }, CLEAR_ANIMATION_MS);
    }
    return () => {
      if (clearAnimTimer.current) {
        clearTimeout(clearAnimTimer.current);
      }
    };
  }, [clearingCells, finishClearingAnimation]);

  useEffect(() => {
    window.addEventListener("mousemove", handleMouseMove);
    window.addEventListener("mouseup", handleMouseUp);
    window.addEventListener("touchmove", handleTouchMove, { passive: false });
    window.addEventListener("touchend", handleTouchEnd, { passive: true });
    window.addEventListener("touchcancel", handleTouchEnd, { passive: true });
    return () => {
      window.removeEventListener("mousemove", handleMouseMove);
      window.removeEventListener("mouseup", handleMouseUp);
      window.removeEventListener("touchmove", handleTouchMove);
      window.removeEventListener("touchend", handleTouchEnd);
      window.removeEventListener("touchcancel", handleTouchEnd);
    };
  }, [handleMouseMove, handleMouseUp, handleTouchMove, handleTouchEnd]);

  const currentChainSet = useMemo(() => {
    const set = new Set<string>();
    const off = dragOffsetRef.current;
    if (isDragging && off && (off.x !== 0 || off.y !== 0)) {
      if (dragChain && dragChain.length > 0) {
        for (const pos of dragChain) {
          set.add(`${pos.row},${pos.col}`);
        }
      } else if (selectedCell) {
        const dir = getDirection(off.x, off.y);
        if (dir) {
          const chain = findPushChain(board, selectedCell.row, selectedCell.col, dir);
          for (const pos of chain) {
            set.add(`${pos.row},${pos.col}`);
          }
        }
      }
    }
    return set;
  }, [isDragging, dragOffsetTick, dragChain, selectedCell, board, getDirection]);

  const clearingSet = useMemo(() => {
    const set = new Set<string>();
    for (const pos of clearingCells) {
      set.add(`${pos.row},${pos.col}`);
    }
    return set;
  }, [clearingCells]);

  const hintSet = useMemo(() => {
    const set = new Set<string>();
    for (const pos of hintCells) {
      set.add(`${pos.row},${pos.col}`);
    }
    return set;
  }, [hintCells]);

  if (board.length === 0) return null;

  return (
    <div
      ref={boardRef}
      className="p-2 sm:p-4 rounded-2xl border-2 border-amber-800/60 shadow-2xl touch-none w-full"
      style={{
        background:
          "linear-gradient(180deg, #a0734a 0%, #8b5e34 50%, #6b4423 100%)",
        boxShadow:
          "inset 0 2px 0 rgba(255,255,255,0.15), inset 0 -2px 0 rgba(0,0,0,0.25), 0 6px 0 rgba(60,35,15,0.6), 0 10px 25px rgba(0,0,0,0.4)",
      }}
    >
      <div
        ref={gridRef}
        data-grid
        className="grid gap-1 touch-none w-full game-board-grid"
        style={{
          gridTemplateColumns: `repeat(${COLS}, minmax(0, 1fr))`,
          gridTemplateRows: `repeat(${ROWS}, minmax(0, 1fr))`,
          aspectRatio: `${COLS} / ${ROWS}`,
        }}
      >
        {board.map((row, rowIdx) =>
          row.map((cell, colIdx) => {
            const key = `${rowIdx},${colIdx}`;
            const isSelected =
              selectedCell?.row === rowIdx && selectedCell?.col === colIdx;
            const isInGroup = groupSet.has(key) && !isSelected;
            const isCandidate = candidateSet.has(key);
            const inChain = currentChainSet.has(key);
            const isClearing = clearingSet.has(key);
            const isShaking = shakingCells.has(key);
            const isHint = hintSet.has(key) && !isSelected && !isCandidate;
            const isSwapFirst = swapFirstCell?.row === rowIdx && swapFirstCell?.col === colIdx;
            const isToolActive = !!activeTool && cell.brick !== null;
            const ox = inChain && isDragging && !isClearing ? dragOffsetRef.current.x : 0;
            const oy = inChain && isDragging && !isClearing ? dragOffsetRef.current.y : 0;

            return (
              <BrickCell
                key={key}
                row={rowIdx}
                col={colIdx}
                brick={cell.brick}
                frozen={cell.frozen}
                isSelected={isSelected}
                isInGroup={isInGroup}
                isCandidate={isCandidate}
                isClearing={isClearing}
                isShaking={isShaking}
                isHint={isHint}
                isSwapFirst={isSwapFirst}
                isToolActive={isToolActive}
                offsetX={ox}
                offsetY={oy}
                onMouseDown={onCellMouseDown}
                onClick={onCellClick}
                onTouchStart={onCellTouchStart}
              />
            );
          })
        )}
      </div>
    </div>
  );
}
